 pub fn next_owned_demand(&self)->Result<RetirementDemand,ValueError>{if self.birth.terminal_is_empty(){if let Some(admission)=self.admission.as_deref(){if admission.phase()=="projectionStart"{return admission.owned_projection_demand()}}}self.next_demand()}
